from pydantic import BaseModel, Field, model_validator


class PlanStep(BaseModel):
    """One actionable step in an implementation plan."""

    step_number: int = Field(ge=1)
    title: str = Field(min_length=3, max_length=100)
    description: str = Field(min_length=10, max_length=1000)
    expected_output: str = Field(min_length=5, max_length=500)


class PlanResponse(BaseModel):
    """Structured implementation plan generated by the Planner."""

    objective: str = Field(min_length=10, max_length=500)
    steps: list[PlanStep] = Field(min_length=1, max_length=8)
    success_criteria: list[str] = Field(min_length=1, max_length=8)

    @model_validator(mode="after")
    def validate_plan(self):
        expected_numbers = list(range(1, len(self.steps) + 1))
        actual_numbers = [step.step_number for step in self.steps]

        if actual_numbers != expected_numbers:
            raise ValueError("Plan step numbers must be sequential and start from 1.")

        if any(not criterion.strip() for criterion in self.success_criteria):
            raise ValueError("Success criteria cannot contain empty values.")

        return self
